'use strict';
// Draft generated by FreeLLMAPI (north-mini-code); reviewed and corrected by Claude.
const { z } = require('zod');

const passwordSchema = z
  .string()
  .min(8, 'Password must be at least 8 characters')
  .max(72, 'Password must be at most 72 characters')
  .regex(/^(?=.*[A-Za-z])(?=.*\d).+$/, 'Password must contain at least one letter and one digit');

const emailSchema = z.string().trim().toLowerCase().email('Enter a valid email').max(254);

const usernameSchema = z
  .string()
  .trim()
  .toLowerCase()
  .regex(/^[a-z0-9_.]{3,30}$/, 'Username must be 3-30 characters: letters, numbers, _ or .');

const displayNameSchema = z.string().trim().min(1, 'Display name is required').max(50);

// Login/current password must NOT enforce the new-password policy.
const anyPassword = z.string().min(1, 'Password is required').max(200);

module.exports = {
  register: z.object({
    email: emailSchema, username: usernameSchema, displayName: displayNameSchema, password: passwordSchema
  }),
  login: z.object({ email: emailSchema, password: anyPassword }),
  refresh: z.object({ refreshToken: z.string().trim().min(1) }),
  changePassword: z.object({ currentPassword: anyPassword, newPassword: passwordSchema }),
  requestReset: z.object({ email: emailSchema }),
  resetPassword: z.object({ token: z.string().trim().min(1), newPassword: passwordSchema })
};
